int list_load(node **head, char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return -1;  // Error opening file
    }

    node *current = NULL;
    node *prev = NULL;

    char buffer[MAX_LINE_LEN];
    while (fgets(buffer, MAX_LINE_LEN, file)!= NULL) {
        buffer[strcspn(buffer, "\n")] = 0;  // Remove newline character

        if (buffer[0] == '\0') continue;  // Skip empty lines

        char *ptr = buffer;
        ptr = strtok(buffer, ",");
        node *new_node = (node *)malloc(sizeof(node));
        new_node->item_name = strdup(ptr);
        ptr = strtok(NULL, ",");
        new_node->price = atof(ptr);
        ptr = strtok(NULL, ",");
        new_node->quantity = atoi(ptr);

        if (*head == NULL) {
            *head = new_node;
            current = *head;
        } else {
            prev->next = new_node;
            current = new_node;
        }
        prev = new_node;
    }

    fclose(file);
    return 0;
}
