    int num_fields = 0;
    int field_start = 0;
    int i;

    for (i = 0; i < strlen(line); i++) {
        if (line[i] == ',') {
            strncpy(fields[num_fields], line + field_start, i - field_start);
            fields[num_fields][i - field_start] = '\0';
            num_fields++;
            field_start = i + 1;
        } else if (line[i] == '\0') {
            strncpy(fields[num_fields], line + field_start, i - field_start);
            fields[num_fields][i - field_start] = '\0';
            num_fields++;
            break;
        }
    }

    // Handle the last field
    if (num_fields < max_fields) {
        strncpy(fields[num_fields], line + field_start, strlen(line) - field_start);
        fields[num_fields][strlen(line) - field_start] = '\0';
        num_fields++;
    }

    return num_fields;
}
