    sprintf(str, "%dx %s @ $", head->quantity, head->item_name);
    sprintf(formatted_price, "%0.2f", head->price);
    str += strlen(str);
    for (int i = 0; i < strlen(formatted_price); i++) {
        *str++ = formatted_price[i];
    }
    *str++ = '\n';
    *str = '\0';

    node *temp = head;
    while (temp->next!= NULL) {
        temp = temp->next;
        quantity += temp->quantity;
        total_price += temp->price * temp->quantity;
    }

    sprintf(str, "Total quantity: %d\nTotal price: $%.2f", quantity, total_price);
    return strlen(str);
