void log_message(const char *message, char *buffer) {
    // Check if the buffer is not null
    if (buffer!= NULL) {
        // Calculate the available space in the buffer
        int available_space = BUFFER_SIZE - strlen(buffer);

        // Copy the message to the buffer, but do not write beyond the available space
        char *ptr = buffer;
        while (*message!= '\0' && available_space > 0) {
            *ptr = *message;
            ptr++;
            message++;
            available_space--;
        }

        // Null-terminate the buffer
        *ptr = '\0';
    }
}
