void log_message(const char *message, char *buffer) {
    // Check if the buffer is not NULL
    if (buffer == NULL) {
        return;
    }

    // Check if the buffer is not empty
    if (strlen(buffer) == 0) {
        // If the buffer is empty, copy the message directly into it
        strcpy(buffer, message);
    } else {
        // If the buffer is not empty, append the message to the end of the buffer
        strcat(buffer, message);
    }

    // Check if the buffer is full
    if (strlen(buffer) >= BUFFER_SIZE) {
        // If the buffer is full, truncate the message to fit the buffer
        buffer[BUFFER_SIZE - 1] = '\0';
    }
}

