void safe_string_copy(char *dest, const char *src, size_t dest_size) {
    size_t src_len = strlen(src);
    if (src_len >= dest_size) {
        // If the source string is longer than the destination buffer, 
        // copy as much as possible and null terminate the rest
        memcpy(dest, src, dest_size - 1);
        dest[dest_size - 1] = '\0';
    } else {
        // If the source string is not longer than the destination buffer, 
        // copy the entire source string and null terminate
        memcpy(dest, src, src_len);
        dest[src_len] = '\0';
    }
}
